def _fw(g, nodes):
    INF = float("inf"); d = {(a, b): (0 if a == b else INF) for a in nodes for b in nodes}
    for a, es in g.items():
        for b, w in es: d[(a, b)] = min(d[(a, b)], w)
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if d[(i, k)] + d[(k, j)] < d[(i, j)]: d[(i, j)] = d[(i, k)] + d[(k, j)]
